# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: to_df(rows) turns pydantic models into a polars DataFrame, one row per model, with
#          column types read from the model's fields (a `date` field is a Date column, also
#          when the list is empty or every value is None), not guessed from JSON text.
# Usage: from ds.util.df import to_df; df = to_df(aapl_daily_closes)
# ---------------------------------------------------------------------------
from __future__ import annotations

import datetime as dt
import types
from typing import Annotated, Any, Literal, Union, get_args, get_origin

import polars as pl
from pydantic import BaseModel

__all__ = ["to_df"]

# checked in this order: bool is an int, datetime is a date
_BASIC: tuple[tuple[type, Any], ...] = (
    (bool, pl.Boolean),
    (int, pl.Int64),
    (float, pl.Float64),
    (str, pl.String),
    (dt.datetime, pl.Datetime("us")),
    (dt.date, pl.Date),
    (dt.time, pl.Time),
    (dt.timedelta, pl.Duration("us")),
)


def _dtype(annotation: Any) -> Any:
    """The polars type of a field's annotation, or None when it is left to polars to infer
    from the values (an enum, a dict, a union of unlike types, Any).
    """
    origin = get_origin(annotation)
    if origin is Annotated:
        return _dtype(get_args(annotation)[0])
    if origin is not None:
        return _generic_dtype(origin, get_args(annotation))
    if not isinstance(annotation, type):
        return None
    if issubclass(annotation, BaseModel):
        fields = _schema(annotation)
        known = all(kind is not None and not _has_datetime(kind) for kind in fields.values())
        return pl.Struct(fields) if known else None
    return next((kind for basic, kind in _BASIC if issubclass(annotation, basic)), None)


def _generic_dtype(origin: Any, args: tuple[Any, ...]) -> Any:
    """_dtype for `X | None`, Literal[...] and list[T] (also tuple, set)."""
    kind = None
    if origin in (Union, types.UnionType):
        kinds = [arg for arg in args if arg is not type(None)]
        kind = _dtype(kinds[0]) if len(kinds) == 1 else (pl.Float64 if set(kinds) == {int, float} else None)
    elif origin is Literal:
        if all(isinstance(value, str) for value in args):
            kind = pl.String
        elif all(type(value) is int for value in args):
            kind = pl.Int64
    elif origin in (list, tuple, set, frozenset):
        inner = [_dtype(arg) for arg in args if arg is not Ellipsis]
        same = len(inner) > 0 and all(item is not None and item == inner[0] for item in inner)
        kind = pl.List(inner[0]) if same and not _has_datetime(inner[0]) else None
    return kind


def _has_datetime(kind: Any) -> bool:
    """A Datetime is only set on an empty column: a value may carry a time zone, which the
    annotation doesn't say, and forcing the type would drop it.
    """
    return kind == pl.Datetime("us")


def _schema(model: type[BaseModel]) -> dict[str, Any]:
    """{column: polars type or None} for a model's fields, computed ones included."""
    fields = {name: _dtype(field.annotation) for name, field in model.model_fields.items()}
    computed = {name: _dtype(field.return_type) for name, field in model.model_computed_fields.items()}
    return {**fields, **computed}


def to_df(rows: BaseModel | list[Any] | tuple[Any, ...], model: type[BaseModel] | None = None) -> pl.DataFrame:
    """Pydantic models as a polars DataFrame: one row per model, one column per field.

    Column types come from the model's fields: date -> Date, float -> Float64, list[int] ->
    List(Int64), a model in a model -> Struct, and so on. A field whose type polars can't be
    told (an enum, a dict, a union of unlike types) holds its JSON form, typed by polars from
    the values.

    rows: one model (one row), or a list of models of one class. model: the class, needed
    only for an empty list (else the frame has no columns). Raises TypeError for anything
    else (a list of basic values, models of more than one class).
    """
    items = [rows] if isinstance(rows, BaseModel) else list(rows)
    classes = {type(item) for item in items}
    if any(not isinstance(item, BaseModel) for item in items) or len(classes) > 1:
        found = ", ".join(sorted(kind.__name__ for kind in classes))
        raise TypeError(f"to_df takes pydantic models of one class, got: {found}")
    model = model or next(iter(classes), None)
    if model is None:
        return pl.DataFrame()
    schema = _schema(model)
    if not items:
        return pl.DataFrame(schema={name: kind or pl.Null for name, kind in schema.items()})
    # a field with no known type is dumped as JSON (an enum as its value), then inferred
    unknown = {name for name, kind in schema.items() if kind is None}
    data = [item.model_dump(exclude=unknown) for item in items]
    if unknown:
        for row, item in zip(data, items, strict=True):
            row.update(item.model_dump(mode="json", include=unknown))
    overrides = {name: kind for name, kind in schema.items() if kind is not None and not _has_datetime(kind)}
    frame = pl.DataFrame(data, schema_overrides=overrides, infer_schema_length=None)
    # a column of only None has no type of its own: give it the field's
    empty = [name for name, kind in schema.items() if kind is not None and frame.schema[name] == pl.Null]
    frame = frame.with_columns(pl.col(name).cast(schema[name]) for name in empty)
    return frame.select(list(schema))
